// M1-H: backend URL configuration, in-memory token management and the typed API client.
// Everything runs against in-memory fakes (no network); the contract test compares the client's requests with the
// OpenAPI document generated by the real FastAPI app. Google and the real token endpoint are NOT involved.

import assert from "node:assert/strict";
import { test } from "node:test";

import { ApiError, createApiClient, createTokenManager, describeError, errorKindForStatus } from "../lib/api-client.ts";
import { ApiConfigError, resolveApiBase, socketUrl } from "../lib/api-config.ts";
import { backendOpenApi, backendPythonAvailable, clock, fakeFetch, json, tokenEndpoint } from "./m1h-helpers.mjs";

const BASE = "https://api.example.com";

function setup({ backend = () => json(200, {}), tokenOptions } = {}) {
  const now = clock();
  const issuer = tokenEndpoint(now, tokenOptions);
  const tokenFetch = fakeFetch(issuer);
  const tokens = createTokenManager({ fetchImpl: tokenFetch, now });
  const backendFetch = fakeFetch(backend);
  const client = createApiClient({ baseUrl: BASE, tokens, fetchImpl: backendFetch });
  return { now, issuer, tokenFetch, tokens, backendFetch, client };
}

// ------------------------------------------------------------------------------------------------ configuration

test("backend URL: validated origin, https only (http for localhost), fail closed in production", () => {
  assert.equal(resolveApiBase("https://api.example.com", true), "https://api.example.com");
  assert.equal(resolveApiBase("  https://api.example.com/  ", true), "https://api.example.com");
  assert.equal(resolveApiBase("https://api.example.com:8443", true), "https://api.example.com:8443");
  assert.equal(resolveApiBase("http://localhost:8000", true), "http://localhost:8000");
  assert.equal(resolveApiBase("http://127.0.0.1:8000", false), "http://127.0.0.1:8000");
  assert.equal(resolveApiBase(undefined, false), "http://localhost:8000", "development default");
  assert.equal(resolveApiBase("", false), "http://localhost:8000");
  for (const [raw, production] of [
    [undefined, true], ["", true], ["   ", true], ["not a url", false], ["http://api.example.com", false], ["ftp://x", false],
    ["https://user:pw@api.example.com", false], ["https://api.example.com/v1", false], ["https://api.example.com/?a=1", false],
    ["https://api.example.com/#frag", false], ["javascript:alert(1)", false], ["//api.example.com", false], ["ws://localhost:8000", false],
  ]) {
    assert.throws(() => resolveApiBase(raw, production), ApiConfigError, String(raw));
  }
  assert.equal(socketUrl("https://api.example.com"), "wss://api.example.com/ws");
  assert.equal(socketUrl("http://localhost:8000"), "ws://localhost:8000/ws");
});

// ------------------------------------------------------------------------------------------------ token manager

test("a token is requested with POST same-origin no-store, held in memory and reused until near expiry", async () => {
  const { tokens, tokenFetch, now } = setup();
  const first = await tokens.get();
  assert.equal(first.token, "token-1");
  assert.equal(tokenFetch.calls.length, 1);
  const { url, init } = tokenFetch.calls[0];
  assert.equal(url, "/api/backend-token");
  assert.equal(init.method, "POST");
  assert.equal(init.credentials, "same-origin");
  assert.equal(init.cache, "no-store");
  assert.equal(init.body, undefined, "no identity is ever sent");
  assert.equal((await tokens.get()).token, "token-1");
  now.advance(539); // 600 s lifetime, 60 s margin: still valid at 539 s
  assert.equal((await tokens.get()).token, "token-1");
  assert.equal(tokenFetch.calls.length, 1);
});

test("a token is reacquired before it expires (60 s margin on the approved 10-minute lifetime)", async () => {
  const { tokens, tokenFetch, now } = setup();
  await tokens.get();
  now.advance(541);
  assert.equal((await tokens.get()).token, "token-2");
  assert.equal(tokenFetch.calls.length, 2);
  now.advance(10_000); // long after expiry
  assert.equal((await tokens.get()).token, "token-3");
});

test("concurrent callers share one acquisition", async () => {
  const { tokens, tokenFetch } = setup();
  const results = await Promise.all(Array.from({ length: 12 }, () => tokens.get()));
  assert.equal(tokenFetch.calls.length, 1);
  assert.ok(results.every((r) => r.token === "token-1"));
});

test("invalidate drops only the token that was rejected; clear forgets everything", async () => {
  const { tokens, tokenFetch } = setup();
  await tokens.get();
  tokens.invalidate("some-other-token");
  assert.equal((await tokens.get()).token, "token-1");
  tokens.invalidate("token-1");
  assert.equal((await tokens.get()).token, "token-2");
  tokens.clear();
  assert.equal((await tokens.get()).token, "token-3");
  assert.equal(tokenFetch.calls.length, 3);
});

test("token acquisition failures are typed and never contain the token", async () => {
  const kinds = [[401, "auth"], [403, "forbidden"], [500, "server"], [503, "server"], [429, "rate_limited"], [405, "server"]];
  for (const [status, kind] of kinds) {
    const { tokens } = setup({ tokenOptions: { fail: () => json(status, { error: "x" }) } });
    await assert.rejects(tokens.get(), (e) => e instanceof ApiError && e.kind === kind && e.status === status, String(status));
  }
  const network = createTokenManager({ fetchImpl: async () => { throw new TypeError("fetch failed token-secret"); } });
  await assert.rejects(network.get(), (e) => e.kind === "network" && !String(e.message).includes("secret"));
  const now = clock();
  for (const body of [{}, { token: "" , expires_at: now() + 600 }, { token: "t" }, { token: 5, expires_at: now() + 600 },
                      { token: "t", expires_at: "soon" }, { token: "t", expires_at: now() - 5 }, { token: "t", expires_at: Number.NaN }, null]) {
    const m = createTokenManager({ fetchImpl: async () => json(200, body), now });
    await assert.rejects(m.get(), (e) => e instanceof ApiError && e.kind === "server", JSON.stringify(body));
  }
  const notJson = createTokenManager({ fetchImpl: async () => new Response("<html>", { status: 200 }), now });
  await assert.rejects(notJson.get(), (e) => e.kind === "server");
  // a failed acquisition is not cached: the next call tries again
  let call = 0;
  const flaky = createTokenManager({ fetchImpl: async () => (++call === 1 ? json(500, {}) : json(200, { token: "ok", expires_at: now() + 600 })), now });
  await assert.rejects(flaky.get());
  assert.equal((await flaky.get()).token, "ok");
});

// ------------------------------------------------------------------------------------------------ requests

test("every protected request carries the bearer token, sends no cookies and no identity", async () => {
  const { client, backendFetch } = setup({ backend: () => json(200, { items: [], next_cursor: null }) });
  await client.getHistory();
  const call = backendFetch.calls[0];
  assert.equal(call.url, `${BASE}/history`);
  assert.equal(call.headers.get("authorization"), "Bearer token-1");
  assert.equal(call.headers.get("accept"), "application/json");
  assert.equal(call.init.credentials, "omit");
  assert.equal(call.init.cache, "no-store");
  assert.equal(call.init.body, undefined);
  assert.equal(call.headers.get("content-type"), null, "no Content-Type on a bodyless GET");
  assert.equal(call.headers.get("x-workspace-id"), null);
  assert.equal(call.headers.get("cookie"), null);
});

test("POST bodies carry only the contract fields", async () => {
  const { client, backendFetch } = setup({ backend: () => json(200, { ok: true }) });
  await client.runAutonomous("sales", "do it");
  await client.scheduleTask({ agent: "ceo", task: "weekly", interval_minutes: 60 });
  const [run, schedule] = backendFetch.calls;
  assert.deepEqual(JSON.parse(run.init.body), { agent: "sales", task: "do it" });
  assert.deepEqual(JSON.parse(schedule.init.body), { agent: "ceo", task: "weekly", interval_minutes: 60 });
  assert.equal(run.headers.get("content-type"), "application/json");
  assert.equal(run.init.method, "POST");
  for (const call of backendFetch.calls) assert.ok(!/email|workspace|user_id/i.test(call.init.body));
});

test("path segments are encoded", async () => {
  const { client, backendFetch } = setup({ backend: () => json(200, { removed: true, id: "x" }) });
  await client.deleteTask("a/b?c=d#e");
  await client.analyzeAgent("ce o");
  assert.equal(backendFetch.calls[0].url, `${BASE}/tasks/a%2Fb%3Fc%3Dd%23e`);
  assert.equal(backendFetch.calls[0].init.method, "DELETE");
  assert.equal(backendFetch.calls[1].url, `${BASE}/improve/ce%20o`);
  assert.equal(backendFetch.calls[1].init.body, undefined, "improve takes no body");
});

// ------------------------------------------------------------------------------------------------ 401 handling

test("a 401 reacquires the token and retries exactly once (also for POST and DELETE: the backend rejects before executing)", async () => {
  for (const [name, call] of [
    ["GET", (c) => c.listTasks()], ["POST", (c) => c.runAutonomous("ceo", "t")], ["DELETE", (c) => c.deleteTask("abc")],
  ]) {
    const { client, backendFetch, tokenFetch } = setup({ backend: (c) => (c.headers.get("authorization") === "Bearer token-1" ? json(401, { detail: "Not authenticated" }) : json(200, [])) });
    await call(client);
    assert.equal(backendFetch.calls.length, 2, name);
    assert.equal(backendFetch.calls[0].headers.get("authorization"), "Bearer token-1");
    assert.equal(backendFetch.calls[1].headers.get("authorization"), "Bearer token-2");
    assert.equal(backendFetch.calls[1].init.method, backendFetch.calls[0].init.method);
    assert.equal(backendFetch.calls[1].init.body, backendFetch.calls[0].init.body, "same request body");
    assert.equal(tokenFetch.calls.length, 2);
  }
});

test("there is no retry loop: a persistent 401 stops after one retry with an auth error", async () => {
  const { client, backendFetch, tokenFetch } = setup({ backend: () => json(401, { detail: "Not authenticated" }) });
  await assert.rejects(client.listTasks(), (e) => e instanceof ApiError && e.kind === "auth" && e.status === 401);
  assert.equal(backendFetch.calls.length, 2);
  assert.equal(tokenFetch.calls.length, 2);
  await assert.rejects(client.runAutonomous("ceo", "t"), (e) => e.kind === "auth");
  assert.equal(backendFetch.calls.length, 4, "each call retries at most once");
});

test("if the retry cannot get a new token, the request is not repeated", async () => {
  const now = clock();
  let acquisitions = 0;
  const tokenFetch = fakeFetch(() => (++acquisitions === 1 ? json(200, { token: "token-1", expires_at: now() + 600 }) : json(401, {})));
  const backendFetch = fakeFetch(() => json(401, {}));
  const client = createApiClient({ baseUrl: BASE, tokens: createTokenManager({ fetchImpl: tokenFetch, now }), fetchImpl: backendFetch });
  await assert.rejects(client.listTasks(), (e) => e.kind === "auth");
  assert.equal(backendFetch.calls.length, 1, "the request is not repeated without a fresh token");
  assert.equal(tokenFetch.calls.length, 2);
});

test("concurrent requests hitting the same expired token share ONE refresh", async () => {
  const { client, backendFetch, tokenFetch } = setup({ backend: (c) => (c.headers.get("authorization") === "Bearer token-1" ? json(401, {}) : json(200, [])) });
  const results = await Promise.all([client.listTasks(), client.listTasks(), client.listTasks(), client.listTasks()]);
  assert.equal(results.length, 4);
  assert.equal(tokenFetch.calls.length, 2, "one initial acquisition + one shared refresh");
  assert.equal(backendFetch.calls.filter((c) => c.headers.get("authorization") === "Bearer token-2").length, 4);
});

test("other statuses and network errors are never retried", async () => {
  for (const [status, kind] of [[403, "forbidden"], [404, "not_found"], [400, "validation"], [422, "validation"], [429, "rate_limited"], [500, "server"], [502, "server"]]) {
    const { client, backendFetch, tokenFetch } = setup({ backend: () => json(status, { detail: "SECRET sql text" }) });
    await assert.rejects(client.runAutonomous("ceo", "t"), (e) => e instanceof ApiError && e.kind === kind && e.status === status && !e.message.includes("SECRET"), String(status));
    assert.equal(backendFetch.calls.length, 1, `${status} must not be retried`);
    assert.equal(tokenFetch.calls.length, 1);
  }
  const { client, backendFetch } = setup({ backend: () => { throw new TypeError("fetch failed: ECONNRESET token-1"); } });
  await assert.rejects(client.scheduleTask({ agent: "ceo", task: "t", interval_minutes: 1 }), (e) => e.kind === "network" && !e.message.includes("token-1"));
  assert.equal(backendFetch.calls.length, 1, "a network error on a POST is not retried (it may have been processed)");
});

test("error kinds are distinguishable and carry fixed user messages", () => {
  const kinds = ["auth", "forbidden", "validation", "not_found", "rate_limited", "server", "network", "config"];
  const messages = new Set(kinds.map((k) => new ApiError(k).userMessage));
  assert.equal(messages.size, kinds.length, "every kind reads differently");
  assert.equal(errorKindForStatus(401), "auth");
  assert.equal(errorKindForStatus(418), "server");
  assert.equal(describeError(new ApiError("network")), new ApiError("network").userMessage);
  assert.equal(describeError(new Error("raw internal text"), "fallback"), "fallback");
  assert.equal(describeError("x"), "Something went wrong. Please try again.");
});

test("a non-JSON success body is a server error, not a crash", async () => {
  const { client } = setup({ backend: () => new Response("<html>oops</html>", { status: 200 }) });
  await assert.rejects(client.listTasks(), (e) => e.kind === "server");
});

// ------------------------------------------------------------------------------------------------ no persistence

test("backend tokens are never written to browser storage, cookies or URLs", async () => {
  const touched = [];
  const spy = (name) => new Proxy({}, { get: (_t, prop) => { touched.push(`${name}.${String(prop)}`); return () => undefined; }, set: () => { touched.push(`${name}=`); return true; } });
  const saved = {};
  for (const name of ["localStorage", "sessionStorage", "indexedDB", "document"]) {
    saved[name] = Object.getOwnPropertyDescriptor(globalThis, name);
    Object.defineProperty(globalThis, name, { value: spy(name), configurable: true, writable: true });
  }
  try {
    const { client, backendFetch, tokenFetch } = setup({ backend: (c) => (c.headers.get("authorization") === "Bearer token-1" ? json(401, {}) : json(200, { items: [], next_cursor: null })) });
    await client.getHistory({ limit: 5, cursor: "v1.x.y" });
    await client.runAutonomous("ceo", "t");
    assert.deepEqual(touched, [], "no storage API was touched");
    for (const call of [...backendFetch.calls, ...tokenFetch.calls]) {
      assert.ok(!/token-\d/.test(call.url), "no token in a URL");
      assert.equal(call.headers.get("cookie"), null);
    }
    for (const call of tokenFetch.calls) assert.equal(call.init.body, undefined);
  } finally {
    for (const [name, descriptor] of Object.entries(saved)) {
      if (descriptor) Object.defineProperty(globalThis, name, descriptor);
      else delete globalThis[name];
    }
  }
});

// ------------------------------------------------------------------------------------------------ history

const ROWS = Array.from({ length: 8 }, (_, i) => ({ id: 80 - i, agent_name: "ceo", summary: `s${i}`, created_at: `2026-03-01T12:00:0${i}` }));

// A fake backend that pages like the real one: opaque cursors, limit default 50, items newest first.
function historyBackend() {
  const handler = (call) => {
    const url = new URL(call.url);
    const limit = Number(url.searchParams.get("limit") ?? 50);
    const cursor = url.searchParams.get("cursor");
    let start = 0;
    if (cursor) {
      const match = /^v1\.c(\d+)\.chk$/.exec(cursor);
      if (!match) return json(400, { detail: "Invalid cursor" });
      start = Number(match[1]);
    }
    const end = start + limit;
    return json(200, { items: ROWS.slice(start, end), next_cursor: end < ROWS.length ? `v1.c${end}.chk` : null });
  };
  handler.cursorAt = (position) => `v1.c${position}.chk`;
  return handler;
}

test("history: query string, response shape and next_cursor are preserved", async () => {
  const { client, backendFetch } = setup({ backend: () => json(200, { items: [ROWS[0]], next_cursor: "v1.abc.def" }) });
  const page = await client.getHistory({ limit: 25, cursor: "v1.prev+/=.zz" });
  assert.deepEqual(page, { items: [ROWS[0]], next_cursor: "v1.abc.def" });
  const url = new URL(backendFetch.calls[0].url);
  assert.equal(url.pathname, "/history");
  assert.equal(url.searchParams.get("limit"), "25");
  assert.equal(url.searchParams.get("cursor"), "v1.prev+/=.zz", "the cursor round-trips exactly");
  assert.ok(!url.search.includes("offset") && !url.search.includes("page="));
});

test("history: following next_cursor returns every record once, in order, with the cursors passed back unchanged", async () => {
  const backend = historyBackend();
  const { client, backendFetch } = setup({ backend });
  const seen = [];
  const cursorsSent = [];
  let cursor = null;
  let pages = 0;
  do {
    const page = await client.getHistory({ limit: 3, cursor });
    seen.push(...page.items.map((item) => item.id));
    cursorsSent.push(new URL(backendFetch.calls.at(-1).url).searchParams.get("cursor"));
    cursor = page.next_cursor;
    pages += 1;
  } while (cursor && pages < 20);
  assert.equal(pages, 3);
  assert.deepEqual(seen, ROWS.map((r) => r.id));
  assert.equal(new Set(seen).size, ROWS.length, "no duplicates");
  assert.deepEqual(cursorsSent, [null, backend.cursorAt(3), backend.cursorAt(6)]);
});

test("history: a malformed response is a server error and a bad cursor is a validation error", async () => {
  for (const body of [[], {}, { items: {}, next_cursor: null }, { items: [], next_cursor: 5 }, { items: [] }, null, "x"]) {
    const { client } = setup({ backend: () => json(200, body) });
    await assert.rejects(client.getHistory(), (e) => e.kind === "server", JSON.stringify(body));
  }
  const { client } = setup({ backend: () => json(400, { detail: "Invalid cursor" }) });
  await assert.rejects(client.getHistory({ cursor: "tampered" }), (e) => e.kind === "validation" && e.status === 400);
});

// ------------------------------------------------------------------------------------------------ real contract

function resolveRef(doc, schema) {
  if (schema?.$ref) return doc.components.schemas[schema.$ref.split("/").pop()];
  return schema;
}

test("the client's requests match the REAL backend's OpenAPI contract", { skip: !backendPythonAvailable }, async () => {
  const doc = backendOpenApi();
  assert.ok(!JSON.stringify(doc).includes("user_email"), "no obsolete email contract remains in the backend");
  const { client, backendFetch } = setup({ backend: () => json(200, { items: [], next_cursor: null }) });
  await client.runAutonomous("ceo", "t");
  await client.listTasks();
  await client.scheduleTask({ agent: "ceo", task: "t", interval_minutes: 5 });
  await client.deleteTask("abc123");
  await client.analyzeAgent("ceo");
  await client.getHistory({ limit: 10, cursor: "v1.a.b" });

  const covered = new Set();
  for (const call of backendFetch.calls) {
    const url = new URL(call.url);
    const method = call.init.method.toLowerCase();
    const template = Object.keys(doc.paths).find((p) => new RegExp(`^${p.replace(/\{[^}]+\}/g, "[^/]+")}$`).test(url.pathname));
    assert.ok(template, `no backend route for ${method} ${url.pathname}`);
    const operation = doc.paths[template][method];
    assert.ok(operation, `backend route ${template} has no ${method.toUpperCase()}`);
    covered.add(`${method} ${template}`);

    const queryNames = (operation.parameters ?? []).filter((p) => p.in === "query").map((p) => p.name);
    for (const name of url.searchParams.keys()) assert.ok(queryNames.includes(name), `unknown query parameter ${name} for ${template}`);

    const schema = resolveRef(doc, operation.requestBody?.content?.["application/json"]?.schema);
    if (call.init.body === undefined) {
      assert.ok(!operation.requestBody?.required, `${template} requires a body the client does not send`);
    } else {
      assert.ok(schema, `${template} takes no JSON body but the client sends one`);
      const body = JSON.parse(call.init.body);
      for (const key of Object.keys(body)) assert.ok(key in schema.properties, `unknown body field ${key} for ${template}`);
      for (const key of schema.required ?? []) assert.ok(key in body, `missing required body field ${key} for ${template}`);
    }
  }
  assert.deepEqual([...covered].sort(), [
    "delete /tasks/{task_id}", "get /history", "get /tasks", "post /autonomous/run", "post /improve/{agent_name}", "post /tasks/schedule",
  ]);
  // the history limit contract the client relies on (default 50, maximum 100)
  const limit = doc.paths["/history"].get.parameters.find((p) => p.name === "limit").schema;
  assert.equal(limit.default, 50);
  assert.equal(limit.maximum, 100);
  assert.equal(limit.minimum, 1);
});
